'use strict';
const SUPPLY_BASE5={fresh,nextWeek,validateSave,takeGreen,processShipments,demandForStore};
let supplyTrace5=null;
function ensureSupply5(v){if(v.supply5===undefined)v.supply5={plans:[],last:null};return v;}
fresh=function(...args){return ensureSupply5(SUPPLY_BASE5.fresh(...args))};state=ensureSupply5(state);
function productionPlan5(r){return state.supply5?.plans.find(p=>p.roaster===r.id)||{roaster:r.id,buffer:1.35,limit:500000,reserve:1.2,allowExpress:true};}
function productionBuffer5(r){return productionPlan5(r).buffer;}
function productionHold5(r,cost,missing,spent){if(!state.supply5?.plans.some(p=>p.roaster===r.id))return state.cash-cost<weeklyFixed()*1.2?'chybí hotovostní rezerva':null;const p=productionPlan5(r);if(missing>.001&&!p.allowExpress)return 'chybí zelená zrna a plán zakazuje expres';if(cost+spent>p.limit)return 'výrobní plán překračuje limit nákupů a zpracování';if(state.cash-cost<weeklyFixed()*p.reserve)return 'chybí hotovostní rezerva';return null;}
function setProductionPlan5(id,data){guard();if(!state.roasters.some(r=>r.id===id)||!data||!Number.isFinite(data.buffer)||data.buffer<.5||data.buffer>3||!Number.isInteger(data.limit)||data.limit<0||data.limit>500000||!Number.isFinite(data.reserve)||data.reserve<1||data.reserve>8||typeof data.allowExpress!=='boolean')throw Error('Plán potřebuje zásobu 0,5–3 týdny, limit 0–500 000 Kč a rezervu 1–8 týdnů.');ensureSupply5(state);state.supply5.plans=state.supply5.plans.filter(p=>p.roaster!==id);state.supply5.plans.push({roaster:id,buffer:data.buffer,limit:data.limit,reserve:data.reserve,allowExpress:data.allowExpress});log('Výrobní plán: '+state.roasters.find(r=>r.id===id).name,'Cílová zásoba '+data.buffer+' týdne, limit '+money(data.limit)+', expres '+(data.allowExpress?'povolen':'zakázán')+'.');}
function resetProductionPlan5(id){guard();ensureSupply5(state);state.supply5.plans=state.supply5.plans.filter(p=>p.roaster!==id);}
function recordSupplyExpress5(origin,kg,cost){if(supplyTrace5){supplyTrace5.express[origin].kg+=kg;supplyTrace5.express[origin].cost+=cost;}}
takeGreen=function(origin,kg){const result=SUPPLY_BASE5.takeGreen(origin,kg);if(supplyTrace5)supplyTrace5.greenUsed[origin]+=kg;return result};
processShipments=function(){const incoming=state.shipments.filter(s=>s.due<=state.week);SUPPLY_BASE5.processShipments();if(supplyTrace5)for(const s of incoming)supplyTrace5.arrivals[s.origin]+=s.kg;};
demandForStore=function(s,factor){const d=SUPPLY_BASE5.demandForStore(s,factor);if(supplyTrace5)supplyTrace5.demands[s.id]={city:loc(s.id).city,blend:s.blend,dose:d.dose||.018,requested:d.potential*(d.dose||.018)};return d};
nextWeek=function(){const previous=supplyTrace5;guard();ensureSupply5(state);supplyTrace5={week:state.week,greenUsed:Object.fromEntries(Object.keys(ORIGINS).map(k=>[k,0])),express:Object.fromEntries(Object.keys(ORIGINS).map(k=>[k,{kg:0,cost:0}])),arrivals:Object.fromEntries(Object.keys(ORIGINS).map(k=>[k,0])),demands:{}};try{const h=SUPPLY_BASE5.nextWeek(),trace=supplyTrace5,cities=[...new Set([...state.stores.map(s=>loc(s.id).city),...state.roasters.map(r=>r.zone),...state.warehouses.map(w=>w.zone)])];state.supply5.last={week:h.week,cash:h.cash,profit:h.profit,spoil:h.spoil,greenUsed:trace.greenUsed,express:trace.express,arrivals:trace.arrivals,greenEnd:Object.fromEntries(Object.keys(ORIGINS).map(k=>[k,greenAmount(k)])),shortages:state.stores.filter(s=>s.last?.stockLost>0).map(s=>({store:s.id,city:loc(s.id).city,blend:s.blend,lost:s.last.stockLost})),cities:cities.map(city=>{const stores=state.stores.filter(s=>loc(s.id).city===city);return {city,stock:cityStock(city),need:stores.reduce((a,s)=>a+(trace.demands[s.id]?.requested||0),0),used:stores.reduce((a,s)=>a+(s.last?.served||0)*(trace.demands[s.id]?.dose||.018),0),lost:stores.reduce((a,s)=>a+(s.last?.stockLost||0),0)};}),roasters:state.roasters.map(r=>({id:r.id,name:r.name,city:r.zone,output:r.last?.output||0,used:r.last?.used||0,capacity:r.last?.capacity||0,holds:(r.last?.decisions||[]).filter(d=>d.includes('pozastaveno')).join(' ')}))};return h;}finally{supplyTrace5=previous}};
function supplyOrderQuote5(orders,reserve=2){if(!Array.isArray(orders)||!orders.length||orders.length>Object.keys(ORIGINS).length||!Number.isFinite(reserve)||reserve<1||reserve>8)throw Error('Vyber alespoň jednu objednávku a rezervu 1–8 týdnů.');const ids=new Set(),items=orders.map(o=>{if(!o||!Object.hasOwn(ORIGINS,o.origin)||ids.has(o.origin)||!Number.isInteger(o.kg)||o.kg<1||o.kg>2500)throw Error('Každý původ smí být jednou a objednávka má 1–2 500 kg.');ids.add(o.origin);return {origin:o.origin,kg:o.kg,unit:getBeanCost(o.origin),due:state.week+1};});return {week:state.week,reserve,items,total:items.reduce((a,o)=>a+o.kg*o.unit,0)};}
function placeSupplyOrders5(orders,reserve=2,expected=null){guard();const quote=supplyOrderQuote5(orders,reserve);if(expected&&(expected.week!==quote.week||JSON.stringify(expected.items)!==JSON.stringify(quote.items)||expected.total!==quote.total))throw Error('Nabídka se změnila. Otevři nový nákupní návrh.');if(state.cash-quote.total<weeklyFixed()*reserve)throw Error('Nákup by porušil nastavenou hotovostní rezervu.');for(const o of quote.items)orderBeans(o.origin,o.kg);return quote;}
function supplyForecast5(weeks=8,factor=1,orders=[]){if(![4,8,13].includes(weeks)||![.85,1,1.15].includes(factor))throw Error('Výhled má 4, 8 nebo 13 týdnů a platnou variantu poptávky.');const original=state,previousTrace=supplyTrace5,series=[];try{state=JSON.parse(JSON.stringify(original));state.forecastDemand=factor;if(orders.length)placeSupplyOrders5(orders,2);for(let i=0;i<weeks&&!state.over;i++){nextWeek();series.push(JSON.parse(JSON.stringify(state.supply5.last)));}const firstLoss=series.find(s=>s.cities.some(c=>c.lost>0)),alerts=[];for(const s of series){for(const c of s.cities)if(c.lost)alerts.push({week:s.week,kind:'stock',target:c.city,text:c.city+': '+[...new Set(s.shortages.filter(x=>x.city===c.city).map(x=>blend(x.blend).name))].join(', ')+' · nedostatek kávy pro '+c.lost+' hostů.'});for(const r of s.roasters){if(r.holds)alerts.push({week:s.week,kind:'plan',target:r.name,text:r.holds});else if(r.capacity&&r.used/r.capacity>.95)alerts.push({week:s.week,kind:'capacity',target:r.name,text:r.name+': výroba přes 95 % kapacity.'});}if(s.spoil)alerts.push({week:s.week,kind:'spoil',target:'Zásoby',text:'Odpis zásob nebo experimentů: '+money(s.spoil)+'.'});}
 const recommendations=Object.keys(ORIGINS).map(origin=>({origin,kg:Math.min(2500,Math.ceil(series.filter(s=>s.week>=original.week+1&&s.week<=original.week+2).reduce((a,s)=>a+s.express[origin].kg,0))),urgent:series[0]?.express[origin].kg||0})).filter(o=>o.kg||o.urgent);
 return {week:original.week,weeks,factor,series,firstLoss:firstLoss?.week??null,alerts,recommendations,over:state.over,finalCash:state.cash,lost:series.reduce((a,s)=>a+s.cities.reduce((b,c)=>b+c.lost,0),0),expressCost:series.reduce((a,s)=>a+Object.values(s.express).reduce((b,o)=>b+o.cost,0),0),greenUsed:Object.fromEntries(Object.keys(ORIGINS).map(k=>[k,series.reduce((a,s)=>a+s.greenUsed[k],0)])),orders:JSON.parse(JSON.stringify(orders))};}finally{state=original;supplyTrace5=previousTrace}}
validateSave=function(input){const v=SUPPLY_BASE5.validateSave(input);ensureSupply5(v);const fail=()=>{throw Error('Soubor obsahuje neplatný plán zásobování.');},n=(x,min=0,max=1e12)=>Number.isFinite(x)&&x>=min&&x<=max,s=v.supply5;if(!s||!Array.isArray(s.plans)||s.plans.length>8||new Set(s.plans.map(p=>p.roaster)).size!==s.plans.length)fail();for(const p of s.plans)if(!v.roasters.some(r=>r.id===p.roaster)||!n(p.buffer,.5,3)||!Number.isInteger(p.limit)||!n(p.limit,0,500000)||!n(p.reserve,1,8)||typeof p.allowExpress!=='boolean')fail();if(s.last){const r=s.last;if(!Number.isInteger(r.week)||r.week<1||r.week>=v.week||!n(r.cash,-1e12)||!n(r.profit,-1e12)||!n(r.spoil)||!['greenUsed','express','arrivals','greenEnd'].every(k=>r[k]&&Object.keys(r[k]).length===Object.keys(ORIGINS).length))fail();for(const k of Object.keys(ORIGINS))if(!n(r.greenUsed[k])||!n(r.arrivals[k])||!n(r.greenEnd[k])||!n(r.express[k]?.kg)||!n(r.express[k]?.cost))fail();if(!Array.isArray(r.shortages)||r.shortages.length>LOCATIONS.length||r.shortages.some(x=>!v.stores.some(s=>s.id===x.store)||!v.blends.some(b=>b.id===x.blend)||!CITIES.some(c=>c.name===x.city)||!Number.isInteger(x.lost)||!n(x.lost)))fail();if(!Array.isArray(r.cities)||r.cities.length>CITIES.length||new Set(r.cities.map(c=>c.city)).size!==r.cities.length||r.cities.some(c=>!CITIES.some(x=>x.name===c.city)||!['stock','need','used','lost'].every(k=>n(c[k]))))fail();if(!Array.isArray(r.roasters)||r.roasters.length>8||r.roasters.some(p=>!v.roasters.some(x=>x.id===p.id)||typeof p.name!=='string'||p.name.length>40||typeof p.holds!=='string'||p.holds.length>3000||!CITIES.some(c=>c.name===p.city)||!['output','used','capacity'].every(k=>n(p[k]))))fail();}return v;};
